import { describe, it, expect, vi } from 'vitest'
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import { ImportGearForm } from './ImportGearForm'

// Mock useAuth hook
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id' }
  })
}))

// Mock supabase
vi.mock('@/lib/supabase', () => ({
  supabase: {
    from: vi.fn(() => ({
      select: vi.fn(() => ({
        eq: vi.fn(() => Promise.resolve({ data: [], error: null }))
      }))
    }))
  }
}))

// Mock the import components
vi.mock('./CsvImport', () => ({
  CsvImport: ({ onImportData }: any) => (
    <div data-testid="csv-import">
      <button onClick={() => onImportData([{ name: 'Test Item', weight_grams: 100, category: 'Test', quantity: 1, worn: false, consumable: false }])}>
        Mock CSV Import
      </button>
    </div>
  )
}))

vi.mock('./UrlImport', () => ({
  UrlImport: ({ onImportData }: any) => (
    <div data-testid="url-import">
      <button onClick={() => onImportData([{ name: 'URL Item', weight_grams: 200, category: 'Test', quantity: 1, worn: false, consumable: false }])}>
        Mock URL Import
      </button>
    </div>
  )
}))

// Use the actual ImportPreview component instead of mocking it

vi.mock('./ImportResults', () => ({
  ImportResults: ({ state, importedCount, onClose }: any) => (
    <div data-testid="import-results">
      <div>State: {state}</div>
      <div>Imported: {importedCount}</div>
      <button onClick={onClose}>Close</button>
    </div>
  )
}))

describe('ImportGearForm', () => {
  const mockOnClose = vi.fn()
  const mockOnImportComplete = vi.fn()

  it('should render with CSV tab by default', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    expect(screen.getByText('CSV File')).toBeInTheDocument()
    expect(screen.getByText('LighterPack URL')).toBeInTheDocument()
    // The CSV tab content should be visible by default
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()
  })

  it('should switch between tabs correctly', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Initially CSV content is visible
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()

    // Click URL tab
    fireEvent.click(screen.getByText('LighterPack URL'))
    // URL content should appear
    await waitFor(() => {
      expect(screen.getByText('Mock URL Import')).toBeInTheDocument()
    })
    // CSV content should be hidden
    expect(screen.queryByText('Mock CSV Import')).not.toBeInTheDocument()

    // Click back to CSV tab
    fireEvent.click(screen.getByText('CSV File'))
    // CSV content should reappear
    await waitFor(() => {
      expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()
    })
    // URL content should be hidden
    expect(screen.queryByText('Mock URL Import')).not.toBeInTheDocument()
  })

  it('should handle CSV import flow', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger CSV import
    fireEvent.click(screen.getByText('Mock CSV Import'))

    // Should show preview
    expect(screen.getByText('Import Preview')).toBeInTheDocument()
    expect(screen.getByText(/1.*Items/)).toBeInTheDocument()
  })

  it('should handle URL import flow', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Switch to URL tab
    fireEvent.click(screen.getByText('LighterPack URL'))

    // Wait for URL content to appear
    await waitFor(() => {
      expect(screen.getByText('Mock URL Import')).toBeInTheDocument()
    })

    // Trigger URL import
    fireEvent.click(screen.getByText('Mock URL Import'))

    // Should show preview
    expect(screen.getByText('Import Preview')).toBeInTheDocument()
    expect(screen.getByText(/1.*Items/)).toBeInTheDocument()
  })

  it('should handle preview confirmation', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import and confirm
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText(/Import.*1.*Items/))

    // Should show results
    expect(screen.getByText('State: importing')).toBeInTheDocument()
  })

  it('should handle preview cancellation', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import and cancel
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText('Back to Import'))

    // Should go back to import form
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()
    expect(screen.queryByText('Import Preview')).not.toBeInTheDocument()
  })

  it('should handle closing the form', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import, confirm, and close
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText(/Import.*1.*Items/))
    fireEvent.click(screen.getByText('Close'))

    expect(mockOnClose).toHaveBeenCalled()
  })

  it('should handle import errors gracefully', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger CSV import
    fireEvent.click(screen.getByText('Mock CSV Import'))

    // Should show preview with items
    expect(screen.getByText('Import Preview')).toBeInTheDocument()
  })
})

import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { supabase } from '@/lib/supabase'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Upload, Link } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportPreview } from './ImportPreview'
import { ImportResults } from './ImportResults'
import type { ParsedGearItem } from '@/utils/csvParser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onImportComplete: (items: ParsedGearItem[]) => Promise<void>
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview' | 'importing' | 'complete'
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

export function ImportGearForm({ onImportComplete, onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('csv')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: []
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const { data, error } = await supabase
          .from('gear_items')
          .select('*')
          .eq('user_id', user.id)

        if (error) throw error
        setExistingItems(data || [])
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on name and brand (case insensitive)
    const importName = importItem.name.toLowerCase().trim()
    const importBrand = (importItem.brand || '').toLowerCase().trim()
    const existingName = existingItem.name.toLowerCase().trim()
    const existingBrand = (existingItem.brand || '').toLowerCase().trim()

    return importName === existingName && importBrand === existingBrand
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata
    })
  }

  const handleConfirmImport = async () => {
    setImportState(prev => ({ ...prev, step: 'importing' }))

    try {
      // Only import new items (not duplicates)
      await onImportComplete(importState.newItems)
      setImportState(prev => ({ ...prev, step: 'complete' }))
    } catch (error) {
      setImportState(prev => ({
        ...prev,
        step: 'preview',
        errors: [...prev.errors, `Import failed: ${error instanceof Error ? error.message : 'Unknown error'}`]
      }))
    }
  }

  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        items={importState.items}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        onConfirm={handleConfirmImport}
        onCancel={handleReset}
        className={className}
      />
    )
  }

  if (importState.step === 'importing' || importState.step === 'complete') {
    return (
      <ImportResults
        state={importState.step}
        importedCount={importState.items.length}
        errors={importState.errors}
        onClose={handleClose}
        onImportMore={handleReset}
        className={className}
      />
    )
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Import Gear</CardTitle>
        <CardDescription>
          Import your gear from LighterPack CSV export or by URL
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="csv" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
          </TabsList>

          <TabsContent value="csv" className="mt-6">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="url" className="mt-6">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-6 pt-4 border-t">
          <Button variant="ghost" onClick={handleClose}>
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

