    expect(screen.queryByText('Mock URL Import')).not.toBeInTheDocument()
  })

  it('should handle CSV import flow', () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger CSV import
    fireEvent.click(screen.getByText('Mock CSV Import'))

    // Should show preview
    expect(screen.getByText('Import Preview')).toBeInTheDocument()
    expect(screen.getByText(/1.*Items/)).toBeInTheDocument()
  })

  it('should handle URL import flow', async () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Switch to URL tab
    fireEvent.click(screen.getByText('LighterPack URL'))

    // Wait for URL content to appear
    await waitFor(() => {
      expect(screen.getByText('Mock URL Import')).toBeInTheDocument()
    })

    // Trigger URL import
    fireEvent.click(screen.getByText('Mock URL Import'))

    // Should show preview
    expect(screen.getByText('Import Preview')).toBeInTheDocument()
    expect(screen.getByText(/1.*Items/)).toBeInTheDocument()
  })

  it('should handle preview confirmation', () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import and confirm
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText(/Import.*1.*Items/))

    // Should show results
    expect(screen.getByText('State: importing')).toBeInTheDocument()
  })

  it('should handle preview cancellation', () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import and cancel
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText('Back to Import'))

    // Should go back to import form
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()
    expect(screen.queryByText('Import Preview')).not.toBeInTheDocument()
  })

  it('should handle closing the form', () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import, confirm, and close
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText(/Import.*1.*Items/))
    fireEvent.click(screen.getByText('Close'))

    expect(mockOnCancel).toHaveBeenCalled()
  })

  it('should handle import errors gracefully', () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger CSV import
    fireEvent.click(screen.getByText('Mock CSV Import'))

    // Should show preview with items
    expect(screen.getByText('Import Preview')).toBeInTheDocument()
  })
})

