import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react'
import { ImportGearForm } from './ImportGearForm'

// Mock useAuth hook
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id' }
  })
}))

// Mock supabase
vi.mock('@/lib/supabase', () => ({
  supabase: {
    from: vi.fn(() => ({
      select: vi.fn(() => ({
        eq: vi.fn(() => Promise.resolve({ data: [], error: null }))
      }))
    }))
  }
}))

// Mock the import components
vi.mock('./CsvImport', () => ({
  CsvImport: ({ onImportData }: any) => (
    <div data-testid="csv-import">
      <button onClick={() => onImportData([{ name: 'Test Item', weight_grams: 100, category: 'Test', quantity: 1, worn: false, consumable: false }])}>
        Mock CSV Import
      </button>
    </div>
  )
}))

vi.mock('./UrlImport', () => ({
  UrlImport: ({ onImportData }: any) => (
    <div data-testid="url-import">
      <button onClick={() => onImportData([{ name: 'URL Item', weight_grams: 200, category: 'Test', quantity: 1, worn: false, consumable: false }])}>
        Mock URL Import
      </button>
    </div>
  )
}))

// Use the actual ImportPreview component instead of mocking it

vi.mock('./ImportResults', () => ({
  ImportResults: ({ state, importedCount, onClose }: any) => (
    <div data-testid="import-results">
      <div>State: {state}</div>
      <div>Imported: {importedCount}</div>
      <button onClick={onClose}>Close</button>
    </div>
  )
}))

describe('ImportGearForm', () => {
  const mockOnCancel = vi.fn()
  const mockOnImportComplete = vi.fn()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('should render with CSV tab by default', async () => {
    await act(async () => {
      render(
        <ImportGearForm
          onCancel={mockOnCancel}
          onImportComplete={mockOnImportComplete}
        />
      )
    })

    expect(screen.getByText('CSV File')).toBeInTheDocument()
    expect(screen.getByText('LighterPack URL')).toBeInTheDocument()
    // The CSV tab content should be visible by default
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()
  })

  it('should switch between tabs correctly', async () => {
    await act(async () => {
      render(
        <ImportGearForm
          onCancel={mockOnCancel}
          onImportComplete={mockOnImportComplete}
        />
      )
    })

    // Initially CSV content is visible
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()

    // Click URL tab
    fireEvent.click(screen.getByText('LighterPack URL'))
    // URL content should appear
    await waitFor(() => {
