    fireEvent.click(screen.getByText('Back to Import'))

    // Should go back to import form
    expect(screen.getByText('Mock CSV Import')).toBeInTheDocument()
    expect(screen.queryByText('Import Preview')).not.toBeInTheDocument()
  })

  it('should handle closing the form', async () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

